// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2014, "8-9", [{"author":"О. Подлесская","question":"Оля записывала то, что можно увидеть и в море, и в ванной. Какое слово попало в её список по ошибке?","choices":["<em>раковина</em>","<em>пена</em>","<em>мочалка</em>","<em>губка</em>","<em>гребешок</em>."],"key":"В","review":["Слова для моря и ванной","Ищи два подходящих значения одного слова. Например, гребешком бывает и морской моллюск, и маленькая расчёска.","Раковина, пена, губка и гребешок могут встретиться и в море, и рядом с ванной. «Мочалка» обычно называет предмет для мытья."]},{"author":"Л. Фёдорова","question":"Кто здесь умеет плавать?","choices":["буква","тыква","брюква","клюква","кряква."],"key":"Д","review":["Кто плавает","Слова похожи по звучанию, но некоторые называют растения или письменный знак. Ищи название птицы.","Кряква — дикая утка, которая умеет плавать. Буква, тыква, брюква и клюква не называют животное."]},{"author":"П. Аркадьев","question":"В каком из слов на месте пропуска нельзя написать ни букву <em>е</em>, ни букву <em>ё</em>?","choices":["<em>странстви</em>__","<em>остри__</em>","<em>быти</em>__","<em>фамили</em>__","во всех этих словах можно написать или букву <em>е</em>, или букву <em>ё</em>."],"key":"Г","review":["Последние буквы слова","Проверь, существуют ли пары с «е» и «ё»: например, «острие» и «остриё» при разных способах передачи «ё» на письме.","«Странствие», «остриё» и «бытие» допускают буквы из условия. В «фамилия» на месте пропуска нужна «я»."]},{"author":"А. Пиперски","question":"От какого мужского имени отчество образуется не совсем таким же образом, как от остальных?","choices":["<em>Глеб</em>","<em>Карл</em>","<em>Марк</em>","<em>Пётр</em>","<em>Ян</em>."],"key":"Г","review":["Отчество от имени","Образуй отчества, например «Глебович» и «Глебовна». Проверь, сохраняет ли имя свою основу.","Глебович, Карлович, Маркович и Янович сохраняют основу имени. От «Пётр» получается «Петрович» и «Петровна», с изменением основы."]},{"author":"Л. Фёдорова","question":"Все данные слова, кроме одного, иностранного происхождения. Кроме какого?","choices":["<em>сарделька</em>","<em>салфетка</em>","<em>окрошка</em>","<em>салат</em>","<em>винегрет</em>."],"key":"В","review":["Происхождение названий еды","Ищи слово, которое можно объяснить через привычный русский глагол о приготовлении еды.","«Окрошка» связана с «крошить» и «окрошить»: продукты мелко режут. Остальные четыре слова заимствованы."]},{"author":"Н. Добрушина","question":"Одна из программ, переводящих текст из латиницы в кириллицу, выдала следующее предложение: <em>Этот замок существовал с ИХ по ХВИИ век</em>. С какого века по какой?","choices":["с 4 по 12","с 9 по 17","с 15 по 20","с 18 по 19","с 20 по 21."],"key":"Б","review":["Века римскими цифрами","Верни кириллическим буквам их латинские прообразы. Для «ХВИИ» получатся знакомые римские знаки.","«ИХ» передаёт IX, то есть 9. «ХВИИ» передаёт XVII, то есть 17. Замок существовал с IX по XVII век."]},{"author":"Л. Фёдорова","question":"Дублёнка — это верхняя одежда","choices":["на двойном меху","на рыбьем меху","на дубовом пуху","из овчины","из баранины."],"key":"Г","review":["Из чего делают дублёнку","Название связано с дублением — обработкой шкур. Ищи подходящее название материала.","Дублёнку делают из овчины, обработанной шкуры овцы. Баранина — название мяса."]},{"author":"О. Подлесская","question":"В каких падежах встречается слово <em>круг</em> в отрывке из стихотворения Г. Сапгира?\n<em>Мчатся волны\nдруг за другом,\nкруг ― за ними,\nя ― за кругом.\n― Дайте круг!\nНе дотянуться!..―\nА кругом,\nКругом смеются:\n― Что на помощь\nты зовёшь?\nИ без круга\nТы плывёшь.</em>","choices":["два раза в им. п., один ― в род. п., один ― в твор. п.","один раз в им. п., один ― в род. п., один ― в вин. п., один ― в твор. п.","два раза в им. п., один ― в род. п., три ― в твор. п.","один раз в им. п., один ― в род. п., один ― в вин. п., три ― в твор. п.","один раз в род. п., два ― в вин. п., три ― в твор. п."],"key":"Б","review":["Падежи слова «круг»","Различи существительное «круг» и наречие «кругом». Подчеркни только формы существительного.","«Круг за ними» — именительный, «дайте круг» — винительный, «за кругом» — творительный, «без круга» — родительный. Наречие «кругом» сюда не входит."]},{"author":"Б. Иомдин","question":"<em>«Наш покровский день мы открываем подходным гудком ещё в постелях. Это мы возвращаемся из ночной Швамбрании. Аннушка терпеливо присутствует при утренней процедуре.\n— Тихай! — командует Оська, отгудев. — Бросай чалку!\nМы сбрасываем одеяла.\n— Стой! Спускай трап!\nМы спускаем ноги.\n— Готово! Приехали! Слезай!\n— С добрым утром!»</em>\n(Лев Кассиль. «Кондуит и Швамбрания»)\nА что такое <em>чалка</em>?","choices":["одеяло","дремота","чулок","жребий","канат."],"key":"Д","review":["Что бросают с судна","Герои обыгрывают действия экипажа у причала. Трап используют для схода с судна, а чалка нужна при швартовке.","Чалка — канат. Его бросают на берег, чтобы подтянуть и закрепить судно у причала."]},{"author":"А. Пиперски","question":"Если спортивный судья допустил ошибку, это — … .","choices":["судейская ошибка","судебная ошибка","судная ошибка","судовая ошибка","судейная ошибка."],"key":"А","review":["Ошибка спортивного судьи","Сравни прилагательные «судейский» и «судебный». Одно связано с судьёй на соревнованиях, другое — с судом.","Ошибку судьи в спортивном состязании называют судейской ошибкой. «Судебная» относится к работе суда."]},{"author":"Н. Добрушина","question":"Ниже приведена эпиграмма А. С. Пушкина с пропущенными чётными строками, где каждая чётная строка рифмуется с предыдущей нечётной.\n<em>Угрюмых тройка есть певцов:\n……………………………………….\nУму есть тройка супостатов:\n……………………………………….\nНо кто глупей из тройки злой?\n……………………………………….</em>\nВ каждой из пропущенных строк в каком-то порядке идут фамилии <em>Шаховской, Шихматов, Шишков</em>. В какой строке для соблюдения ритма Пушкин добавил после первой фамилии слово <em>наш</em>?","choices":["во второй","в четвёртой","в шестой","ни в какой","во всех."],"key":"Б","review":["Рифмы в эпиграмме","Вместе три фамилии дают восемь слогов. Посмотри, какой строке нужен ещё один слог из-за безударного окончания рифмы.","«Певцо́в» и «зло́й» завершаются ударным слогом. В «супоста́тов» после ударения есть ещё слог, и в четвёртой строке добавлено «наш», чтобы получить девять слогов."]},{"author":"Е. Бикмаев","question":"Определите род каждого из существительных: <em>суп-пюре, интернет-пространство, Ильмень-озеро</em>.","choices":["мужской, мужской, средний","мужской, средний, мужской","средний, средний, мужской","средний, средний, средний","мужской, средний, средний."],"key":"Д","review":["Род сложных существительных","В каждом названии выдели слово, которое называет сам предмет: еду, пространство или водоём.","«Суп-пюре» — мужского рода, «интернет-пространство» и «Ильмень-озеро» — среднего. Род определяют «суп», «пространство» и «озеро»."]},{"author":"Л. Фёдорова","question":"Как не называют человека?","choices":["<em>стреляный воробей</em>","<em>белая ворона</em>","<em>ранняя пташка</em>","<em>гусь лапчатый</em>","<em>дрозд крапчатый</em>."],"key":"Д","review":["Птичьи названия людей","Проверь, у каких сочетаний есть устойчивый переносный смысл: например, «белая ворона» обозначает человека, выделяющегося среди других.","«Стреляный воробей» — опытный человек, «ранняя пташка» рано встаёт, «гусь лапчатый» — хитрец. «Дрозд крапчатый» не служит таким названием человека."]},{"author":"Л. Фёдорова","question":"Между какими цветами радуги нужно поместить бирюзовый цвет?","choices":["между красным и оранжевым","между оранжевым и жёлтым","между жёлтым и зелёным","между зелёным и голубым","между синим и фиолетовым."],"key":"Г","review":["Цвет в радуге","Вспомни, какими словами описывают оттенок бирюзы, если называют сразу два цвета.","Бирюзовый — голубовато-зелёный оттенок. Его помещают между зелёным и голубым."]},{"author":"П. Аркадьев","question":"Что в Древнем Риме получал в награду человек, которого называли <em>лауреатом</em>?","choices":["тысячу серебряных монет","диплом на пергаменте","лавровый венок","красную тогу","пальмовую ветвь."],"key":"В","review":["Награда в Древнем Риме","Слово «лауреат» связано с латинским названием растения. Из его ветвей делали знак награды.","Латинское «laurus» означает «лавр». Лауреат — увенчанный лавром, то есть получивший лавровый венок."]},{"author":"Б. Иомдин","question":"<em>Кто-нибудь стриг себя ____?</em> Каким словом точно нельзя заменить пропуск в этом вопросе?","choices":["<em>сам</em>","<em>сама</em>","<em>самого</em>","<em>саму</em>","<em>самоё</em>."],"key":"Б","review":["Согласование со словом «сам»","Определи, относится ли форма к тому, кто стриг, или к тому, кого стригли. Проверь падеж в каждом варианте.","С «кто-нибудь стриг» согласуется «сам», а с «себя» могут сочетаться «самого», «саму», «самоё». Форма «сама» требует подлежащего женского рода, которого в вопросе нет."]},{"author":"Л. Фёдорова","question":"Греческая буква Г называется <em>гамма</em>. А какая буква древнегреческого алфавита называлась <em>дигамма</em>?","choices":["E","F","H","Κ","Λ."],"key":"Б","review":["Древнегреческая буква","«Ди-» в названии указывает на два. Сравни очертания вариантов с заглавной гаммой «Г».","Буква дигамма похожа на F: у неё две горизонтальные черты, словно у двух гамм, поставленных одна над другой."]},{"author":"Е. Муравенко","question":"В каком из предложений, взятых с разных сайтов в интернете, нет ошибки в употреблении падежа?","choices":["<em>Посылка может быть перенаправлена в другое почтовое учреждение по заявлению получателя</em>.","<em>Билет на поезд можно купить лишь по предъявлению паспорта</em>.","<em>По приезду в Москву иностранцы должны оформить регистрацию</em>.","<em>Визу можно оформить по прилёту в Китай в аэропорту</em>.","<em>Главный тренер заверил, что покинет команду по окончанию сезона</em>."],"key":"А","review":["Падеж после предлога «по»","Различи основание для действия и действие, после которого что-то случается. Сравни «по заявлению» с «по окончании».","«По заявлению» значит «на основании заявления» и употреблено правильно. В остальных фразах нужно «по предъявлении», «по приезде», «по прилёте» и «по окончании»."]},{"author":"Л. Фёдорова","question":"Какое из этих выражений реже остальных встречается в конце предложения?","choices":["<em>ни дать ни взять</em>","<em>ни встать ни сесть</em>","<em>ни слуху ни духу</em>","<em>ни к селу ни к городу</em>","<em>ни туда ни сюда</em>."],"key":"А","review":["Оборот в конце фразы","Прочитай обороты как завершение предложения. Один из них обычно требует после себя слово для сравнения.","«Ни дать ни взять» часто ставят перед сравнением: «ни дать ни взять настоящий актёр». Остальные обороты нормально завершают высказывание."]},{"author":"Е. Добрушина","question":"В каком из этих слов буква перед <em>к</em> читается не так, как обычно, не по общим правилам русского произношения?","choices":["<em>близкий</em>","<em>гладкий</em>","<em>тяжкий</em>","<em>мягкий</em>","<em>яркий</em>."],"key":"Г","review":["Согласный перед «к»","Вспомни, как звонкие согласные обычно оглушаются перед «к». Затем проведи такую проверку для «г» в слове «мягкий».","В «мягкий» перед «к» произносится мягкий [х’]. Простое оглушение [г] дало бы звук [к], поэтому это особый случай."]},{"author":"Б. Иомдин","question":"Какое слово не родственно остальным?","choices":["<em>жим</em>","<em>жатва</em>","<em>жмых</em>","<em>жмот</em>","<em>сжатие</em>."],"key":"Б","review":["Разные значения «жать»","Различи «жать» со значением «сжимать» и «жать» со значением «срезать хлеб».","«Жатва» связана со срезанием хлеба. «Жим», «жмых», «жмот» и «сжатие» связаны с давлением или удерживанием."]},{"author":"Б. Иомдин","question":"В большинстве четырёхтомных изданий словаря В. И. Даля целый том занимают слова на букву … .","choices":["<em>А</em>","<em>М</em>","<em>П</em>","<em>Т</em>","<em>Я.</em>"],"key":"В","review":["Тома словаря Даля","Вспомни, с какой буквы начинается много слов с продуктивными приставками «по-», «под-», «пере-» и «при-».","Слова на «П» занимают у Даля отдельный том. На эту букву начинаются многочисленные слова с перечисленными приставками."]},{"author":"А. Пиперски","question":"Дан отрывок из романа А. С. Пушкина «Евгений Онегин»:\n<em>Латынь из моды вышла ныне:\nТак, если правду вам сказать,\nОн знал довольно по-латыне,\nЧтоб эпиграфы разбирать…</em>\nКакие из этих четырёх строк содержат отступления от норм современного русского языка?","choices":["только вторая","только третья","только четвёртая","вторая и третья","третья и четвёртая."],"key":"Д","review":["Язык «Евгения Онегина»","Проверь, как сегодня пишется наречие о латыни и куда падает ударение в «эпиграфы». Затем прочитай строки по ритму.","В третьей строке «по-латыне», сегодня пишут «по-латыни». В четвёртой ямб требует «эпигра́фы», тогда как современное ударение — «эпи́графы»."]},{"author":"П. Аркадьев","question":"В каком из приведённых порядковых числительных последние две буквы относятся не к окончанию, а к суффиксу?","choices":["<em>первый</em>","<em>второй</em>","<em>третий</em>","<em>четвёртый</em>","ни в каком."],"key":"В","review":["Суффикс порядкового числа","Просклоняй числительные и проверь, как ведут себя их последние буквы. Например, «первый» меняется на «первого».","«Третий» склоняется как «третий — третьего — третьему». В начальной форме «-ий» передаёт суффикс с йотовым элементом, окончание нулевое."]},{"author":"П. Аркадьев","question":"Женское имя <em>Полина</em> исторически восходит к тому же корню, что и мужское имя … .","choices":["<em>Пётр</em>","<em>Поликарп</em>","<em>Филипп</em>","<em>Леонид</em>","<em>Павел</em>."],"key":"Д","review":["Родство двух имён","Сопоставь «Полина» с французским «Pauline». Подбери мужское имя той же семьи.","«Pauline» восходит к латинскому «Paulus». Из того же имени происходит русское «Павел»."]},{"author":"Т. Заболотская","question":"Даны слова: 1) <em>ссуженый</em>; 2) <em>ссуженный</em>; 3) <em>суженый</em>; 4) <em>суженный</em>.\nВ каких из них точно допущена орфографическая ошибка?","choices":["только в 1","только в 1 и 4","в 2 и 3","во всех, кроме 3","ни в одном."],"key":"А","review":["Одно или два «н»","Проверь три значения: дать деньги взаймы, сделать что-то более узким и назвать будущего супруга.","«Ссуженный» пишут о том, что дали взаймы, «суженный» — о том, что стало уже, «суженый» — о будущем муже. Ошибка только в «ссуженый»."]},{"author":"А. Сомин","question":"Дана статья из Малого энциклопедического словаря Брокгауза и Ефрона 1907–1909 гг. выпуска, в которой пропущено одно слово: «Сутки, период оборота Земли вокруг своей оси (звёздные сутки = 23 часа 56 мин. 4 сек.). В _____ сутки считаются в 24 часа». Какое слово мы пропустили?","choices":["<em>гостинице</em>","<em>интернате</em>","<em>общежитии</em>","<em>пансионате</em>","<em>санатории</em>."],"key":"В","review":["Сутки по старому словарю","Рассмотри варианты как слова о повседневной жизни. В старом тексте знакомое название могло иметь более широкое значение.","Здесь «общежитие» означает обычную жизнь людей. В повседневном счёте сутки принимаются за 24 часа."]},{"author":"А. Пиперски","question":"Дан список: <em>бдеть</em>, <em>зреть</em>, <em>греть</em>, <em>млеть</em>, <em>тлеть</em>. Сколько в этом списке можно обнаружить глаголов I спряжения и сколько ― глаголов II спряжения?","choices":["1 и 5","2 и 4","3 и 3","4 и 2","5 и 1."],"key":"Г","review":["Два значения и спряжение","Поставь глаголы в формы «ты» и «они». Для «зреть» проверь два значения: созревать и видеть.","К I спряжению относятся «греешь», «млеешь», «тлеешь», «зреешь». Ко II — «бдишь» и «зришь». Получается четыре и два глагола."]},{"author":"Е. Муравенко","question":"Данные числительные русского языка восходят к соответствующим числительным праславянского языка (общего предка всех славянских языков). Какое из русских числительных утратило парный по глухости/звонкости согласный звук, имевшийся в исходном праславянском слове?","choices":["<em>шесть</em>","<em>семь</em>","<em>восемь</em>","<em>девять</em>","<em>десять</em>."],"key":"Б","review":["Старый согласный в числе","Сравни числительные с порядковыми формами. Одна из них сохранила согласный, которого сейчас нет в количественном числительном.","В праславянском предке «семь» был согласный [д], судя по форме «седьмой». У [д] есть глухая пара [т]."]},{"author":"А. Сомин","question":"Слово <em>Россия</em> на китайский язык переводится как 俄罗斯, а другое русское слово — как 白俄罗斯. Что означает иероглиф 白?","choices":["‘холодный’","‘чёрный’","‘белый’","‘красивый’","‘ровный’."],"key":"В","review":["Иероглиф в названии страны","Сравни обе китайские записи и выдели добавленный знак. Вспомни русское название соседней с Россией страны, связанное с цветом.","В «Белоруссия» есть часть «бел-». Ей соответствует добавленный иероглиф 白 со значением «белый»."]}], {"year":2014,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2014.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
